import type { DesignContent } from "@/lib/design-content";

export const content: DesignContent = {"slug": "global-search", "title": "UniShare · Global search", "css": "\n:root{--ink:#14201e;--muted:#5b6866;--teal:#0b5b57;--teal-soft:#e3efed;--line:#14201e;--hair:#dfe4e3;--panel:#f4f6f5;--white:#fff}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\"Schibsted Grotesk\",system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--ink);background:var(--white);font-size:14px;line-height:1.45}\na{color:inherit;text-decoration:none}\nbutton,input,select{font:inherit;color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:2px solid var(--teal);outline-offset:2px}\n.nav{border-bottom:2px solid var(--line);height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 48px;gap:24px}\n.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:20px}\n.brand svg{width:24px;height:24px;color:var(--teal)}\n.nav ul{list-style:none;display:flex;gap:22px;font-size:13px}\n.nav ul a{padding:19px 0;display:block;border-bottom:2px solid transparent;margin-bottom:-2px}\n.nav ul a.on{color:var(--teal);font-weight:600;border-color:var(--teal)}\n.nav-r{display:flex;align-items:center;gap:18px;font-size:13px}\n.nav-r svg.i{width:15px;height:15px}\n.bell{display:flex;align-items:flex-start;gap:2px;color:var(--teal)}\n.bell sup{font-size:8px;font-weight:600;margin-top:2px}\n.sos{display:flex;align-items:center;gap:5px;font-weight:600;color:var(--teal)}\n.user{display:flex;align-items:center;gap:8px}\n.avatar{width:28px;height:28px;border-radius:50%;background:var(--teal-soft);border:1px solid var(--teal);color:var(--teal);font-size:10px;display:grid;place-items:center;font-weight:600}\n.user b{font-weight:600;font-size:12px;line-height:1.2;display:block}\n.user small{display:block;color:var(--muted);font-size:10px;line-height:1.2}\nmain{max-width:786px;margin:0 auto;padding:0 0 48px}\n.crumbs{font-size:11px;color:var(--muted);margin:19px 0 24px;display:flex;gap:6px}\n.eyebrow{font-size:9.5px;letter-spacing:.04em;color:var(--teal);font-weight:600;text-transform:uppercase;margin-bottom:10px}\nh1{font-size:30px;line-height:1.1;font-weight:800;letter-spacing:-.01em;margin-bottom:10px}\n.lede{color:var(--muted);font-size:13px;margin-bottom:26px}\n.search{display:flex;align-items:center;gap:10px;border:1.5px solid var(--line);border-radius:8px;padding:4px 4px 4px 14px;margin-bottom:24px}\n.search>svg{width:15px;height:15px;flex:none;color:var(--teal)}\n.search input{flex:1;border:0;outline:0;background:transparent;font-size:13px;padding:8px 0;min-width:0}\n.search:focus-within{outline:2px solid var(--teal);outline-offset:2px}\n.x{border:0;background:none;color:var(--teal);font-size:18px;line-height:1;padding:4px 8px}\n.search .go{background:var(--teal);color:#fff;border:0;border-radius:6px;padding:11px 18px;font-weight:700;font-size:12.5px;white-space:nowrap}\n.search .go:hover{background:#094a47}\n.tabs{display:flex;gap:24px;border-bottom:2px solid var(--hair);margin-bottom:20px;font-size:12px}\n.tabs button{background:none;border:0;border-bottom:2px solid transparent;margin-bottom:-2px;padding:8px 0 12px}\n.tabs button.on{color:var(--teal);font-weight:700;border-color:var(--teal)}\n.filters{display:flex;gap:8px;margin-bottom:24px;flex-wrap:wrap;align-items:center}\n.filters .sp{flex:1}\n.fb{display:inline-flex;align-items:center;gap:8px;border:1.5px solid var(--teal);color:var(--teal);background:#fff;border-radius:8px;padding:0 12px;height:34px;font-weight:600;font-size:12px}\n.fb svg{width:13px;height:13px;flex:none}\n.fb:hover{background:var(--teal-soft)}\n.fb[aria-pressed=\"true\"]{background:var(--teal-soft)}\n.fb select{appearance:none;-webkit-appearance:none;border:0;background:transparent;color:var(--teal);font-weight:600;font-size:12px;outline:0;cursor:pointer}\n.sec{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:14px}\n.sec h2{font-size:18px;font-weight:700}\n.sec span{font-size:11px;color:var(--muted)}\n.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:32px}\n.item{border:1.5px solid var(--line);border-radius:12px;overflow:hidden;background:#fff;display:flex;flex-direction:column}\n.photo{position:relative;height:132px;background:var(--panel)}\n.photo img{width:100%;height:100%;object-fit:cover;display:block}\n.avail{position:absolute;top:8px;left:8px;background:rgba(255,255,255,.93);border-radius:999px;padding:3px 9px;font-size:9.5px;font-weight:500}\n.heart{position:absolute;top:8px;right:8px;width:24px;height:24px;border-radius:50%;border:0;background:rgba(255,255,255,.95);display:grid;place-items:center}\n.heart svg{width:14px;height:14px;fill:none;stroke:var(--teal);stroke-width:2;stroke-linejoin:round}\n.heart.on svg{fill:var(--teal)}\n.body{padding:14px 12px 12px;display:flex;flex-direction:column;flex:1}\n.cat{font-size:9.5px;color:var(--muted)}\n.body h3{font-size:13px;font-weight:700;margin:8px 0 8px;line-height:1.3}\n.rate{font-size:14px;font-weight:700;color:var(--teal);margin-bottom:5px}\n.dep{font-size:9.5px;color:var(--muted);margin-bottom:8px}\n.loc{display:flex;align-items:center;gap:5px;font-size:9.5px;color:var(--muted);padding-bottom:10px;border-bottom:1px solid var(--hair);margin-bottom:10px}\n.loc svg{width:10px;height:10px;color:var(--teal)}\n.owner{display:flex;align-items:flex-start;gap:7px;margin-bottom:12px}\n.owner>svg{width:13px;height:13px;color:var(--teal);flex:none;margin-top:1px}\n.owner b{display:block;font-size:10px;font-weight:700;line-height:1.3}\n.owner small{font-size:9.5px;color:var(--muted)}\n.btn{border:1.5px solid var(--teal);color:var(--teal);background:#fff;border-radius:8px;padding:10px 16px;font-weight:600;font-size:12px;white-space:nowrap;display:inline-flex;align-items:center;gap:8px}\n.btn:hover{background:var(--teal-soft)}\n.btn svg{width:13px;height:13px}\n.btn.sm{padding:7px 12px;font-size:10.5px;align-self:flex-start;margin-top:auto}\n.rides{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-bottom:22px}\n.ride{border:1.5px solid var(--line);border-radius:12px;padding:20px 16px 16px}\n.rtop{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}\n.car svg{width:15px;height:15px;color:var(--teal)}\n.seats{background:var(--teal-soft);color:var(--teal);font-size:9.5px;font-weight:600;border-radius:999px;padding:4px 10px}\n.ride h3{font-size:18px;font-weight:700;margin-bottom:12px;line-height:1.25}\n.ride p{font-size:11.5px;color:var(--muted);margin-bottom:12px}\n.ride .rate{font-size:14px;margin-bottom:20px}\n.rfoot{display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:10px;color:var(--muted)}\n.rfoot .btn.sm{margin-top:0}\n.sub{font-size:11px;color:var(--muted);margin-top:-8px;max-width:420px}\n.ridehead{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:16px}\n.ridehead h2{font-size:19px;font-weight:700;margin-bottom:6px}\n.empty{display:none;border:1.5px dashed var(--teal);border-radius:12px;padding:30px 20px;text-align:center;color:var(--muted);font-size:13px;margin-bottom:24px}\n.empty b{display:block;color:var(--ink);font-size:15px;margin-bottom:4px}\n.notice{background:var(--teal-soft);border-radius:8px;padding:14px 18px;display:flex;gap:12px;margin-top:10px}\n.notice svg{width:16px;height:16px;color:var(--teal);flex:none;margin-top:2px}\n.notice b{display:block;color:var(--teal);font-size:11.5px;margin-bottom:2px}\n.notice span{font-size:10.5px;color:var(--muted)}\nfooter{border-top:2px solid var(--line);padding:22px 48px 26px;display:flex;justify-content:space-between;font-size:11.5px;color:var(--muted)}\nfooter nav{display:flex;gap:22px}\nfooter nav a{color:var(--teal);font-weight:600}\n@media (max-width:1040px){.nav ul{display:none}}\n@media (max-width:820px){.cards{grid-template-columns:repeat(2,1fr)}}\n@media (max-width:760px){\n  main{padding:0 20px 40px}\n  .nav,footer{padding-left:20px;padding-right:20px}\n  .rides{grid-template-columns:1fr}\n  .filters .sp{display:none}\n  .ridehead{flex-direction:column}\n  footer{flex-direction:column;gap:10px}\n}\n@media (max-width:480px){.cards{grid-template-columns:1fr}.sec{flex-direction:column;gap:4px}}\n", "body": "\n<header class=\"nav\">\n  <a class=\"brand\" href=\"/\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"7\" cy=\"12\" r=\"4\"/><circle cx=\"17\" cy=\"12\" r=\"4\"/></svg>UniShare</a>\n  <ul>\n    <li><a href=\"/campus-home\">Home</a></li><li><a class=\"on\" href=\"/marketplace\">Marketplace</a></li><li><a href=\"/my-products\">My products</a></li><li><a href=\"/my-rentals\">My rentals</a></li><li><a href=\"/ride-home-and-search\">Rides</a></li><li><a href=\"/wallet-overview\">Wallet</a></li><li><a href=\"/favorites\">Favorites</a></li>\n  </ul>\n  <div class=\"nav-r\">\n    <span class=\"bell\" aria-label=\"3 notifications\"><svg class=\"i\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M6 17V11a6 6 0 0 1 12 0v6l1.5 2h-15zM10 21h4\"/></svg><sup>3</sup></span>\n    <a class=\"sos\" href=\"/student-sos-assistance\"><svg class=\"i\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/><path d=\"M9 12l2 2 4-4\" stroke-linecap=\"round\"/></svg>SOS</a>\n    <div class=\"user\"><span class=\"avatar\">FR</span><div><b>Farhana Rahman</b><small>My profile</small></div></div>\n  </div>\n</header>\n\n<main>\n  <nav class=\"crumbs\" aria-label=\"Breadcrumb\"><a href=\"/campus-home\">Home</a><span>›</span><span>Find it on your campus</span></nav>\n  <div class=\"eyebrow\">University of Dhaka · Verified students only</div>\n  <h1>Find it on your campus</h1>\n  <p class=\"lede\">Search items and shared rides within the University of Dhaka community.</p>\n\n  <label class=\"search\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"12\" cy=\"12\" r=\"6\"/></svg>\n    <input id=\"q\" type=\"search\" value=\"TSC\" aria-label=\"Search campus\">\n    <button class=\"x\" id=\"x\" type=\"button\" aria-label=\"Clear search\">×</button>\n    <button class=\"go\" id=\"go\" type=\"button\">Search campus</button>\n  </label>\n\n  <div class=\"tabs\" id=\"tabs\" role=\"tablist\">\n    <button class=\"on\" role=\"tab\" data-t=\"items\" type=\"button\">Items (<span id=\"ni\">3</span>)</button>\n    <button role=\"tab\" data-t=\"rides\" type=\"button\">Rides (<span id=\"nr\">2</span>)</button>\n  </div>\n\n  <div class=\"filters\">\n    <button class=\"fb\" type=\"button\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"4\" y=\"5\" width=\"16\" height=\"15\" rx=\"2\"/><path d=\"M4 10h16M9 5V3M15 5V3\"/></svg>Rental dates</button>\n    <label class=\"fb\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg><select aria-label=\"Category\"><option>All categories</option><option>Laptop chargers</option><option>Cameras</option><option>Travel essentials</option></select></label>\n    <label class=\"fb\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg><select aria-label=\"Token price\"><option>Token price</option><option>Under 40 tokens</option><option>40–60 tokens</option></select></label>\n    <button class=\"fb\" id=\"availBtn\" type=\"button\" aria-pressed=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.5l4.5 4.5L19 7.500\"/></svg>Available now</button>\n    <span class=\"sp\"></span>\n    <label class=\"fb\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg><select id=\"sort\" aria-label=\"Sort\"><option value=\"rel\">Sort: Relevance</option><option value=\"low\">Sort: Price, low to high</option><option value=\"high\">Sort: Price, high to low</option></select></label>\n  </div>\n\n  <section id=\"itemsView\">\n    <div class=\"sec\"><h2 id=\"h2\">Items matching “TSC”</h2><span id=\"meta\">3 results · Pickup near TSC</span></div>\n    <div class=\"cards\" id=\"cards\">\n        <article class=\"item\" data-rate=\"50\" data-i=\"0\" data-text=\"laptop charger · 65w laptop chargers tsc maliha islam\">\n          <div class=\"photo\"><img src=\"data:image/jpeg;base64,\" alt=\"Laptop charger · 65W\"><span class=\"avail\">Available</span>\n            <button class=\"heart\" type=\"button\" aria-pressed=\"false\" aria-label=\"Save Laptop charger · 65W to Favorites\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 21s-7.5-4.6-9.5-9.2C1.2 8.6 3 5 6.6 5c2 0 3.5 1 5.4 3 1.9-2 3.4-3 5.4-3 3.6 0 5.4 3.6 4.1 6.8C19.5 16.4 12 21 12 21z\"/></svg></button></div>\n          <div class=\"body\">\n            <small class=\"cat\">Laptop chargers · Good</small>\n            <h3>Laptop charger · 65W</h3>\n            <div class=\"rate\">50 tokens / day</div>\n            <div class=\"dep\">100 tokens refundable deposit</div>\n            <div class=\"loc\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 21s7-6.2 7-11.5A7 7 0 0 0 5 9.5C5 14.8 12 21 12 21z\"/><circle cx=\"12\" cy=\"9.5\" r=\"2.5\"/></svg>TSC, University of Dhaka</div>\n            <div class=\"owner\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M8 12.500l2.800 2.800L16 9.500\"/></svg><div><b>Maliha Islam</b><small>Verified DU student</small></div></div>\n            <a class=\"btn sm\" href=\"/product-details\">View item</a>\n          </div>\n        </article>\n        <article class=\"item\" data-rate=\"60\" data-i=\"1\" data-text=\"canon eos 200d cameras tsc farhana rahman\">\n          <div class=\"photo\"><img src=\"data:image/jpeg;base64,\" alt=\"Canon EOS 200D\"><span class=\"avail\">Available</span>\n            <button class=\"heart\" type=\"button\" aria-pressed=\"false\" aria-label=\"Save Canon EOS 200D to Favorites\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 21s-7.5-4.6-9.5-9.2C1.2 8.6 3 5 6.6 5c2 0 3.5 1 5.4 3 1.9-2 3.4-3 5.4-3 3.6 0 5.4 3.6 4.1 6.8C19.5 16.4 12 21 12 21z\"/></svg></button></div>\n          <div class=\"body\">\n            <small class=\"cat\">Cameras · Good</small>\n            <h3>Canon EOS 200D</h3>\n            <div class=\"rate\">60 tokens / day</div>\n            <div class=\"dep\">300 tokens refundable deposit</div>\n            <div class=\"loc\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 21s7-6.2 7-11.5A7 7 0 0 0 5 9.5C5 14.8 12 21 12 21z\"/><circle cx=\"12\" cy=\"9.5\" r=\"2.5\"/></svg>TSC, University of Dhaka</div>\n            <div class=\"owner\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M8 12.500l2.800 2.800L16 9.500\"/></svg><div><b>Farhana Rahman · You</b><small>Verified DU student</small></div></div>\n            <a class=\"btn sm\" href=\"/product-details\">View item</a>\n          </div>\n        </article>\n        <article class=\"item\" data-rate=\"30\" data-i=\"2\" data-text=\"hiking backpack · 30l travel essentials tsc sadia islam\">\n          <div class=\"photo\"><img src=\"data:image/jpeg;base64,\" alt=\"Hiking backpack · 30L\"><span class=\"avail\">Available</span>\n            <button class=\"heart\" type=\"button\" aria-pressed=\"false\" aria-label=\"Save Hiking backpack · 30L to Favorites\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 21s-7.5-4.6-9.5-9.2C1.2 8.6 3 5 6.6 5c2 0 3.5 1 5.4 3 1.9-2 3.4-3 5.4-3 3.6 0 5.4 3.6 4.1 6.8C19.5 16.4 12 21 12 21z\"/></svg></button></div>\n          <div class=\"body\">\n            <small class=\"cat\">Travel essentials · Good</small>\n            <h3>Hiking backpack · 30L</h3>\n            <div class=\"rate\">30 tokens / day</div>\n            <div class=\"dep\">100 tokens refundable deposit</div>\n            <div class=\"loc\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 21s7-6.2 7-11.5A7 7 0 0 0 5 9.5C5 14.8 12 21 12 21z\"/><circle cx=\"12\" cy=\"9.5\" r=\"2.5\"/></svg>TSC, University of Dhaka</div>\n            <div class=\"owner\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M8 12.500l2.800 2.800L16 9.500\"/></svg><div><b>Sadia Islam</b><small>Verified DU student</small></div></div>\n            <a class=\"btn sm\" href=\"/product-details\">View item</a>\n          </div>\n        </article>\n    </div>\n    <div class=\"empty\" id=\"emptyItems\"><b>No items found</b>Try another place or item name.</div>\n  </section>\n\n  <section id=\"ridesView\">\n    <div class=\"ridehead\">\n      <div><h2>Going the same way?</h2><p class=\"sub\" id=\"rsub\">2 rides also match “TSC”. Explore the Rides tab for route filters.</p></div>\n      <button class=\"btn\" id=\"viewRides\" type=\"button\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg>View ride results</button>\n    </div>\n    <div class=\"rides\" id=\"rides\">\n        <article class=\"ride\" data-text=\"dhanmondi 27 → tsc, du arif hossain\">\n          <div class=\"rtop\"><span class=\"car\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 16V11l2-5h10l2 5v5M3 16h18v2H3zM7 13h.01M17 13h.01\"/><path d=\"M5 11h14\"/></svg></span><span class=\"seats\">2 seats left</span></div>\n          <h3>Dhanmondi 27 → TSC, DU</h3>\n          <p>Today · 8:30 AM · Car</p>\n          <div class=\"rate\">80 tokens / seat</div>\n          <div class=\"rfoot\"><span>Arif Hossain · Verified DU student</span><a class=\"btn sm\" href=\"/product-details\">Details</a></div>\n        </article>\n        <article class=\"ride\" data-text=\"tsc, du → mirpur 10 tanvir ahmed\">\n          <div class=\"rtop\"><span class=\"car\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 16V11l2-5h10l2 5v5M3 16h18v2H3zM7 13h.01M17 13h.01\"/><path d=\"M5 11h14\"/></svg></span><span class=\"seats\">2 seats left</span></div>\n          <h3>TSC, DU → Mirpur 10</h3>\n          <p>Today · 4:30 PM · Car</p>\n          <div class=\"rate\">100 tokens / seat</div>\n          <div class=\"rfoot\"><span>Tanvir Ahmed · Verified DU student</span><a class=\"btn sm\" href=\"/product-details\">Details</a></div>\n        </article>\n    </div>\n    <div class=\"empty\" id=\"emptyRides\"><b>No rides found</b>Try a different stop or route.</div>\n  </section>\n\n  <div class=\"notice\" role=\"note\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/><path d=\"M9 12l2 2 4-4\"/></svg>\n    <div><b>Your university, and only your university.</b><span>Results are limited to verified DU students. Meet in public campus spots and complete bookings with tokens.</span></div>\n  </div>\n</main>\n\n<footer>\n  <span>UniShare. Made for university students in Bangladesh.</span>\n  <nav><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/get-help\">Get help</a><a href=\"/\">Log out</a></nav>\n</footer>\n\n\n", "scripts": ["\n(function(){\n  var q=document.getElementById('q'),cards=document.getElementById('cards'),sort=document.getElementById('sort');\n  var items=Array.prototype.slice.call(cards.children),rides=Array.prototype.slice.call(document.getElementById('rides').children);\n  var itemsView=document.getElementById('itemsView'),ridesView=document.getElementById('ridesView'),tabs=document.getElementById('tabs');\n  var tab='items';\n  function render(){\n    var term=q.value.trim().toLowerCase();\n    var list=items.slice().sort(function(a,b){return sort.value==='low'?a.dataset.rate-b.dataset.rate:sort.value==='high'?b.dataset.rate-a.dataset.rate:a.dataset.i-b.dataset.i});\n    var ni=0,nr=0;\n    list.forEach(function(el){cards.appendChild(el);var ok=!term||el.dataset.text.indexOf(term)>-1;el.style.display=ok?'':'none';if(ok)ni++});\n    rides.forEach(function(el){var ok=!term||el.dataset.text.indexOf(term)>-1;el.style.display=ok?'':'none';if(ok)nr++});\n    document.getElementById('ni').textContent=ni;document.getElementById('nr').textContent=nr;\n    var label=q.value.trim();\n    document.getElementById('h2').textContent=label?'Items matching “'+q.value.trim()+'”':'All items';\n    document.getElementById('meta').textContent=ni+(ni===1?' result':' results')+(label?' · Pickup near '+q.value.trim():'');\n    document.getElementById('rsub').textContent=nr+(nr===1?' ride also matches':' rides also match')+' “'+q.value.trim()+'”. Explore the Rides tab for route filters.';\n    document.getElementById('emptyItems').style.display=ni?'none':'block';\n    document.getElementById('emptyRides').style.display=nr?'none':'block';\n    document.getElementById('rides').style.display=nr?'':'none';\n    itemsView.style.display=tab==='items'?'':'none';\n    ridesView.style.display='';\n    ridesView.querySelector('.ridehead').style.display=tab==='items'?'':'none';\n    if(tab==='rides'){ridesView.querySelector('.ridehead').style.display='none'}\n  }\n  tabs.addEventListener('click',function(e){\n    var b=e.target.closest('button');if(!b)return;\n    Array.prototype.forEach.call(tabs.children,function(x){x.classList.remove('on')});\n    b.classList.add('on');tab=b.dataset.t;render();\n  });\n  document.getElementById('viewRides').addEventListener('click',function(){\n    tabs.querySelector('[data-t=rides]').click();window.scrollTo({top:0,behavior:'smooth'});\n  });\n  document.getElementById('go').addEventListener('click',render);\n  q.addEventListener('keydown',function(e){if(e.key==='Enter')render()});\n  q.addEventListener('input',render);\n  document.getElementById('x').addEventListener('click',function(){q.value='';q.focus();render()});\n  sort.addEventListener('change',render);\n  var av=document.getElementById('availBtn');\n  av.addEventListener('click',function(){av.setAttribute('aria-pressed',av.getAttribute('aria-pressed')!=='true')});\n  document.querySelectorAll('.heart').forEach(function(h){\n    h.addEventListener('click',function(){var on=h.classList.toggle('on');h.setAttribute('aria-pressed',on)});\n  });\n  render();\n})();\n"], "fonts": ["https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@400;500;600;700;800&display=swap"]};

